import{_ as r,o as a,c as t,au as o}from"./chunks/framework.BTTEhLNX.js";const f=JSON.parse('{"title":"krawler-meteoradar","description":"A Krawler based service to download public Rainfall Radar data from MeteoFrance.","frontmatter":{"title":"krawler-meteoradar","description":"A Krawler based service to download public Rainfall Radar data from MeteoFrance."},"headers":[],"relativePath":"packages/krawler-meteoradar/index.md","filePath":"packages/krawler-meteoradar/index.md"}'),n={name:"packages/krawler-meteoradar/index.md"};function i(d,e,l,s,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-meteoradar" tabindex="-1">krawler-meteoradar <a class="header-anchor" href="#krawler-meteoradar" aria-label="Permalink to &quot;krawler-meteoradar&quot;">​</a></h1><p><em>A Krawler based service to download public <a href="https://donneespubliques.meteofrance.fr/?fond=produit&amp;id_produit=98&amp;id_rubrique=34" target="_blank" rel="noreferrer">Rainfall Radar data from MeteoFrance</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-meteoradar</strong> job scrapes public Radar rainfall data from Meteo France public server. The downloaded images are stored in PNG format without any georeference information. The job first georeferenced the image and then converts it to <a href="https://www.cogeo.org/" target="_blank" rel="noreferrer">COG format</a> and copies it to a store.</p><p>The major part of the process is done using <a href="https://gdal.org/index.html" target="_blank" rel="noreferrer">GDAL</a>.</p><p>The job scrapes the data according a specific cron expression. By default every 15 minutes.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>STORE_PATH</code></td><td>The path where to store the files</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><p>Setting the <strong>STORE_PATH</strong> environment variable triggers files copy to a predefined store using <a href="https://rclone.org/" target="_blank" rel="noreferrer">Rclone</a>. It is then required to define the remote store using <a href="https://rclone.org/docs/#environment-variables" target="_blank" rel="noreferrer">Rclone environment variables</a>.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',11)])])}const m=r(n,[["render",i]]);export{f as __pageData,m as default};
